    void payments(){frame("پرداخت‌ها",true);managerDrawer();section("پرداخت‌های ساکنان","هر پرداخت به شارژ، هزینه یا تعمیر مربوط است");callFinance("manager_finance_dashboard",new JSONObject(),j->{JSONArray p=j.optJSONArray("payments");if(p==null||p.length()==0){empty("هنوز پرداختی ثبت نشده است");return;}for(int i=0;i<p.length();i++){JSONObject x=p.optJSONObject(i);if(x==null)continue;LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(15),dp(12),dp(15),dp(12));c.setBackground(box(white,19));c.addView(tv(x.optString("item_title","پرداخت"),17,navy));c.addView(tv("واحد "+x.optString("unit_no","-")+" • "+financeMoney(x.optDouble("amount")),13,muted));c.addView(tv("تاریخ: "+financeDate(x.optString("paid_at",x.optString("created_at")))+" • "+paymentFa(x.optString("status")),12,statusColor(x.optString("status"))));LinearLayout row=new LinearLayout(this);Button doc=btn("مشاهده فیش",gold),edit=btn("ویرایش",blue);row.addView(doc,new LinearLayout.LayoutParams(0,dp(45),1));row.addView(edit,new LinearLayout.LayoutParams(0,dp(45),1));c.addView(row);doc.setOnClickListener(v->showReceipt(x.optString("receipt_url","")));edit.setOnClickListener(v->financePaymentEdit(x));if("pending".equals(x.optString("status"))){Button ok=btn("✓ تأیید پرداخت",green),no=btn("✕ رد پرداخت",red);LinearLayout rr=new LinearLayout(this);rr.addView(ok,new LinearLayout.LayoutParams(0,dp(45),1));rr.addView(no,new LinearLayout.LayoutParams(0,dp(45),1));c.addView(rr);ok.setOnClickListener(v->approveFinance(x.optString("id"),true));no.setOnClickListener(v->approveFinance(x.optString("id"),false));}content.addView(c,new LinearLayout.LayoutParams(-1,-2));content.addView(gap(10));}});}
    void approveFinance(String id,boolean ok){callFinance("approve_payment_finance",new JSONObject().put("payment_id",id).put("approved",ok),z->{toast(ok?"پرداخت تأیید شد":"پرداخت رد شد");payments();});}
    void financePaymentEdit(JSONObject x){final EditText a=input("مبلغ به تومان"),n=input("توضیحات");a.setText(String.valueOf(Math.round(x.optDouble("amount")/10.0)));n.setText(x.optString("note",""));LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.addView(a,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));l.addView(n,new LinearLayout.LayoutParams(-1,dp(54)));new AlertDialog.Builder(this).setTitle("ویرایش پرداخت").setView(dialogScroll(l)).setNegativeButton("لغو",null).setPositiveButton("ذخیره",(d,w)->callFinance("update_payment_finance",new JSONObject().put("payment_id",x.optString("id")).put("amount_rial",Math.max(0,parseMoney(a.getText().toString())*10)).put("note",n.getText().toString()),z->{toast("پرداخت ویرایش شد");payments();})).show();}
    void plans(){frame("اشتراک سامانه",true);managerDrawer();section("وضعیت اشتراک ساختمان","وضعیت، تاریخ شروع و تاریخ پایان باید همیشه برای مدیر قابل مشاهده باشد");call("subscription_status",j->{String st=j.optString("status",j.optString("subscription_status","expired"));String start=j.optString("starts_at","-");String end=j.optString("ends_at",j.optString("expires_at","-"));int c=("active".equalsIgnoreCase(st)||"trial".equalsIgnoreCase(st))?green:red;item("اشتراک فعلی",statusFa(st));item("شروع اشتراک",start);item("پایان اشتراک",end);});call("my_requests",j->{JSONArray r=j.optJSONArray("data");if(r!=null&&r.length()>0){section("درخواست‌های من","آخرین درخواست و وضعیت فیش پرداخت");for(int i=0;i<r.length();i++){JSONObject q=r.optJSONObject(i);if(q==null)continue;String st=q.optString("status","pending");String plan=q.optJSONObject("subscription_plans")!=null?q.optJSONObject("subscription_plans").optString("name","طرح"):"طرح";item(plan,statusFa(st)+"  •  "+(q.optString("receipt_path","").isEmpty()?"فیش ثبت نشده":"فیش ثبت شده"));}}});section("طرح‌های قابل خرید","خرید جدید پس از تأیید مدیرکل فعال می‌شود");call("list_plans",j->{JSONArray a=j.optJSONArray("data");if(a==null||a.length()==0){empty("در حال حاضر طرح فعالی وجود ندارد");return;}for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)planCard(x);}});}
