    void planCard(JSONObject x){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(13),dp(16),dp(13));c.setBackground(grad(Color.WHITE,Color.rgb(248,251,252),20));TextView h=tv(x.optString("name","طرح"),18,navy);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);c.addView(h);long price=Math.round(x.optDouble("price_rial"));int days=x.optInt("duration_days");c.addView(tv(money(price)+"  •  "+days+" روز",13,teal));Button b=btn(price>0?"خرید و ثبت درخواست":"فعال‌سازی طرح رایگان",teal);c.addView(b,new LinearLayout.LayoutParams(-1,dp(47)));b.setOnClickListener(v->requestPlan(x));content.addView(c,new LinearLayout.LayoutParams(-1,-2));content.addView(gap(9));}
    void requestPlan(JSONObject x){io.submit(()->{try{JSONObject q=new JSONObject().put("action","request_subscription").put("plan_id",x.optString("id"));JSONObject j=new JSONObject(post(q,session));if(j.has("error"))throw new Exception(j.getString("error"));JSONObject rq=j.optJSONObject("request"); pendingRequestId=rq!=null?rq.optString("id",""):j.optString("request_id",j.optString("id",""));long price=Math.round(x.optDouble("price_rial"));runOnUiThread(()->{if(price>0&& !pendingRequestId.isEmpty()) chooseReceipt();else toast("درخواست اشتراک ثبت شد و در انتظار تأیید مدیرکل است");});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()==null?"خطا در ثبت درخواست":e.getMessage()));}});}
    void chooseReceipt(){new AlertDialog.Builder(this).setTitle("ارسال فیش پرداخت").setMessage("برای تکمیل درخواست اشتراک، تصویر یا PDF فیش بانکی را انتخاب کنید.").setNegativeButton("بعداً",null).setPositiveButton("انتخاب فیش",(d,w)->pickReceipt()).show();}
    void pickReceipt(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/jpeg","image/png","image/webp","application/pdf"});startActivityForResult(i,701);}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode!=701||resultCode!=RESULT_OK||data==null||data.getData()==null)return;Uri u=data.getData();io.submit(()->{try{java.io.InputStream in=getContentResolver().openInputStream(u);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[8192];int n,total=0;while((n=in.read(buf))!=-1){total+=n;if(total>10*1024*1024)throw new Exception("حجم فیش بیشتر از ۱۰ مگابایت است");out.write(buf,0,n);}in.close();String mime=getContentResolver().getType(u);if(mime==null)mime="application/octet-stream";JSONObject q=new JSONObject().put("action","upload_receipt").put("request_id",pendingRequestId).put("mime_type",mime).put("file_base64",Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP));JSONObject j=new JSONObject(post(q,session));if(j.has("error"))throw new Exception(j.getString("error"));runOnUiThread(()->toast("فیش با موفقیت ارسال شد؛ درخواست در انتظار تأیید مدیرکل است"));}catch(Exception e){runOnUiThread(()->toast(e.getMessage()==null?"خطا در ارسال فیش":e.getMessage()));}});}
