    void residentPayItem(JSONObject x,boolean charge){final EditText a=input("مبلغ پرداخت به تومان"),n=input("توضیحات / شماره پیگیری"),date=jalaliInput("تاریخ پرداخت");double share=x.optJSONObject("my_allocation")!=null?x.optJSONObject("my_allocation").optDouble("allocated_amount_rial"):0;a.setText(String.valueOf(Math.round(share/10.0)));receiptData="";receiptButton=btn("＋ آپلود فیش پرداخت",green);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);for(EditText e:new EditText[]{a,n,date}){l.addView(e,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));}l.addView(receiptButton,new LinearLayout.LayoutParams(-1,dp(50)));receiptButton.setOnClickListener(v->{uploadTarget=2;pickImage();});new AlertDialog.Builder(this).setTitle("پرداخت: "+x.optString("title")).setView(dialogScroll(l)).setNegativeButton("لغو",null).setPositiveButton("ارسال پرداخت",(d,w)->{long rial=Math.max(0,parseMoney(a.getText().toString())*10);callFinance("pay_item_finance",new JSONObject().put("amount_rial",rial).put(charge?"charge_id":"repair_id",x.optString("id")).put("paid_at",jalaliToIso(date)).put("note",n.getText().toString()).put("receipt_url",receiptData),z->{receiptData="";receiptButton=null;toast("پرداخت برای همین مورد ثبت شد");residentHome();});}).show();}
