    void subscriptionRequestCard(JSONObject q){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(15),dp(12),dp(15),dp(12));c.setBackground(box(white,19));String st=q.optString("status","pending");c.addView(tv("درخواست اشتراک",16,navy));c.addView(tv("ساختمان: "+q.optString("building_id","-"),12,muted));c.addView(tv("مبلغ: "+money(q.optDouble("amount_rial")),12,teal));c.addView(tv("وضعیت: "+statusFa(st),13,statusColor(st)));if(!q.optString("receipt_path","").isEmpty()){Button rv=btn("مشاهده فیش پرداخت",blue);c.addView(rv,new LinearLayout.LayoutParams(-1,dp(48)));rv.setOnClickListener(v->viewReceipt(q.optString("id")));}if("pending".equals(st)){LinearLayout row=new LinearLayout(this);Button ok=btn("تأیید و فعال‌سازی",green),no=btn("رد درخواست",red);row.addView(ok,new LinearLayout.LayoutParams(0,dp(48),1));row.addView(no,new LinearLayout.LayoutParams(0,dp(48),1));c.addView(row);ok.setOnClickListener(v->callObj(new JSONObject().put("action","admin_subscription_action").put("request_id",q.optString("id")).put("status","approved"),z->adminHome()));no.setOnClickListener(v->callObj(new JSONObject().put("action","admin_subscription_action").put("request_id",q.optString("id")).put("status","rejected"),z->adminHome()));}content.addView(c,new LinearLayout.LayoutParams(-1,-2));content.addView(gap(9));}
    void viewReceipt(String id){io.submit(()->{try{JSONObject j=new JSONObject(post(new JSONObject().put("action","admin_get_receipt").put("request_id",id),session));String url=j.optString("signed_url",j.optString("url",""));if(url.isEmpty())throw new Exception("فیش در دسترس نیست");runOnUiThread(()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){toast("امکان باز کردن فیش وجود ندارد");}});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()==null?"خطا در دریافت فیش":e.getMessage()));}});}
    void adminSettings(){frame("تنظیمات سامانه",true);adminDrawer();section("تنظیمات فعلی","پارامترهای اصلی سامانه");call("admin_dashboard",j->{JSONObject x=j.optJSONObject("settings");if(x!=null){item("نام برنامه",x.optString("app_name"));item("دوره آزمایشی",x.optString("free_trial_days")+" روز");item("تأیید ایمیل",x.optBoolean("email_verification_enabled")?"فعال":"غیرفعال");item("درگاه پرداخت",x.optBoolean("payment_gateway_enabled")?"فعال":"غیرفعال");}});}
    void callFinance(String action, JSONObject body, OnJson cb){
        final int t=screenToken; JSONObject b=body==null?new JSONObject():body; b.put("action",action);
        io.submit(()->{try{JSONObject j=new JSONObject(postTo(b,session,FINANCE_API));if(j.has("error"))throw new Exception(j.getString("error"));runOnUiThread(()->{if(t==screenToken&&cb!=null)cb.ok(j);});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()==null?"خطای سامانه مالی":e.getMessage()));}});
    }
    String postTo(JSONObject body,String bearer,String endpoint)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(endpoint).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(15000);c.setReadTimeout(25000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=UTF-8");if(bearer!=null&&!bearer.isEmpty())c.setRequestProperty("Authorization","Bearer "+bearer);c.getOutputStream().write(body.toString().getBytes(StandardCharsets.UTF_8));int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();BufferedReader br=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8));StringBuilder z=new StringBuilder();String line;while((line=br.readLine())!=null)z.append(line);if(code>=400){try{JSONObject e=new JSONObject(z.toString());throw new Exception(e.optString("error","خطای سامانه مالی ("+code+")"));}catch(org.json.JSONException ex){throw new Exception("خطای سامانه مالی ("+code+")");}}return z.toString();}
    String financeMoney(double v){return money(v);}
    String financeDate(String iso){return JalaliDate.format(iso);}
    String paymentFa(String s){if("approved".equals(s))return "🟢 تأیید شده";if("rejected".equals(s))return "🔴 رد شده";return "🟡 در انتظار تأیید";}
    void showReceipt(String value){if(value==null||value.isEmpty()){toast("فیش یا مدرکی ثبت نشده است");return;}try{if(value.startsWith("data:image")){String b64=value.substring(value.indexOf(',')+1);byte[] raw=Base64.decode(b64,Base64.DEFAULT);ImageView iv=new ImageView(this);iv.setAdjustViewBounds(true);iv.setScaleType(ImageView.ScaleType.FIT_CENTER);iv.setImageBitmap(BitmapFactory.decodeByteArray(raw,0,raw.length));new AlertDialog.Builder(this).setTitle("مشاهده فیش / مدرک").setView(iv).setPositiveButton("بستن",null).show();}else{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(value)));}}catch(Exception e){toast("نمایش فیش امکان‌پذیر نیست");}}
    EditText jalaliInput(String title){EditText e=input(title+" (شمسی)");e.setText(JalaliDate.now());return e;}
    String jalaliToIso(EditText e){String x=JalaliDate.toGregorianIso(e.getText().toString().trim());return x.isEmpty()?new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new java.util.Date()):x;}
    void financeUnitPicker(LinearLayout box, JSONArray units, ArrayList<String> selected, TextView summary){final ArrayList<String> labels=new ArrayList<>();for(int i=0;i<units.length();i++){JSONObject u=units.optJSONObject(i);if(u!=null)labels.add("واحد "+u.optString("unit_no","-"));}boolean[] checked=new boolean[labels.size()];for(int i=0;i<units.length();i++){JSONObject u=units.optJSONObject(i);if(u!=null&&selected.contains(u.optString("id")))checked[i]=true;}new AlertDialog.Builder(this).setTitle("انتخاب واحدهای مشمول").setMultiChoiceItems(labels.toArray(new String[0]),checked,(d,which,isChecked)->{JSONObject u=units.optJSONObject(which);if(u==null)return;String id=u.optString("id");if(isChecked&&!selected.contains(id))selected.add(id);if(!isChecked)selected.remove(id);}).setPositiveButton("تأیید",(d,w)->summary.setText(selected.size()+" واحد انتخاب شد")).setNegativeButton("لغو",null).show();}
    void financeCreateDialog(boolean repair){
        callFinance("manager_finance_dashboard",new JSONObject(),j->{JSONArray units=j.optJSONArray("units");if(units==null||units.length()==0){toast("ابتدا حداقل یک واحد ثبت کنید");return;}final EditText title=input(repair?"عنوان تعمیر":"عنوان شارژ / هزینه"),amt=input("مبلغ کل به تومان"),desc=input("توضیحات"),date=jalaliInput(repair?"تاریخ تعمیر":"تاریخ هزینه");final RadioGroup scope=new RadioGroup(this);scope.setOrientation(RadioGroup.VERTICAL);RadioButton all=new RadioButton(this);all.setText("کل ساکنین / همه واحدها");all.setTextSize(14);RadioButton selected=new RadioButton(this);selected.setText("فقط واحدهای انتخاب‌شده");selected.setTextSize(14);all.setChecked(true);scope.addView(all);scope.addView(selected);final ArrayList<String> ids=new ArrayList<>();final TextView summary=tv("همه واحدها انتخاب شده‌اند",12,muted);final Button choose=btn("☑ انتخاب واحدها",blue);choose.setVisibility(View.GONE);selected.setOnCheckedChangeListener((v,on)->{choose.setVisibility(on?View.VISIBLE:View.GONE);summary.setVisibility(on?View.VISIBLE:View.GONE);});choose.setOnClickListener(v->financeUnitPicker(null,units,ids,summary));final Spinner split=new Spinner(this);ArrayList<String> methods=new ArrayList<>();methods.add("تقسیم مساوی بین واحدها");methods.add("تقسیم بر اساس تعداد ساکنین");split.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,methods));Button receipt=btn("＋ آپلود فاکتور / عکس",repair?red:gold);receiptData="";receiptButton=receipt;receipt.setOnClickListener(v->{uploadTarget=repair?3:1;pickImage();});LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(10),0,dp(10),0);l.addView(title,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));l.addView(amt,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));l.addView(date,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));l.addView(desc,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(8));l.addView(scope,new LinearLayout.LayoutParams(-1,dp(78)));l.addView(summary,new LinearLayout.LayoutParams(-1,dp(30)));l.addView(choose,new LinearLayout.LayoutParams(-1,dp(48)));l.addView(tv("نحوه تقسیم مبلغ",12,muted),new LinearLayout.LayoutParams(-1,dp(28)));l.addView(split,new LinearLayout.LayoutParams(-1,dp(50)));l.addView(gap(8));l.addView(receipt,new LinearLayout.LayoutParams(-1,dp(50)));new AlertDialog.Builder(this).setTitle(repair?"ثبت تعمیر جدید":"ثبت شارژ / هزینه جدید").setView(dialogScroll(l)).setNegativeButton("لغو",null).setPositiveButton("ثبت",(d,w)->{long rial=Math.max(0,parseMoney(amt.getText().toString())*10);if(rial<=0){toast("مبلغ را وارد کنید");return;}boolean allOn=all.isChecked();if(!allOn&&ids.isEmpty()){toast("حداقل یک واحد را انتخاب کنید");return;}String method=split.getSelectedItemPosition()==1?"per_person":"per_unit";JSONObject body=new JSONObject().put("amount_rial",rial).put("title",title.getText().toString().trim()).put("description",desc.getText().toString().trim()).put("all_units",allOn).put("unit_ids",new JSONArray(ids)).put("allocation_method",method).put("receipt_url",receiptData);if(repair)body.put("repair_date",jalaliToIso(date));else body.put("charge_date",jalaliToIso(date));callFinance(repair?"add_repair_finance":"add_charge_finance",body,z->{receiptData="";receiptButton=null;toast(repair?"تعمیر ثبت شد":"هزینه ثبت شد");if(repair)repairs();else charges();});}).show();});
    }
    void call(String action,OnJson cb){callObj(new JSONObject().put("action",action),cb);}
    void callObj(JSONObject b,OnJson cb){final int t=screenToken;io.submit(()->{try{JSONObject j=new JSONObject(post(b,session));if(j.has("error"))throw new Exception(j.getString("error"));runOnUiThread(()->{if(t==screenToken&&cb!=null)cb.ok(j);});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()==null?"خطای سامانه":e.getMessage()));}});}
    interface OnJson{void ok(JSONObject j);}
    String post(JSONObject body,String bearer)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(API).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=UTF-8");if(bearer!=null&&!bearer.isEmpty())c.setRequestProperty("Authorization","Bearer "+bearer);c.getOutputStream().write(body.toString().getBytes(StandardCharsets.UTF_8));int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();BufferedReader br=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();String line;while((line=br.readLine())!=null)s.append(line);if(code>=400)throw new Exception("خطای سامانه ("+code+")");return s.toString();}
    long parseMoney(String s){try{return Long.parseLong(s.replace(",","").replace("٬","").trim());}catch(Exception e){return 0;}}
    String money(double rial){long toman=Math.round(rial/10.0);return String.format(Locale.US,"%,d تومان",toman);}
    String statusFa(String s){if("approved".equals(s))return "تأیید شده";if("rejected".equals(s))return "رد شده";if("pending".equals(s))return "در انتظار بررسی";return s==null?"-":s;}
    int statusColor(String s){if("approved".equals(s))return green;if("rejected".equals(s))return red;return gold;}
    void toast(String s){Toast.makeText(this,s==null?"خطا":s,Toast.LENGTH_LONG).show();}

    @Override public void onBackPressed(){if(drawer!=null&&drawer.getVisibility()==View.VISIBLE){drawer.setVisibility(View.GONE);return;}if(history.size()>1){history.removeLast();show(history.peekLast());return;}if(!role.isEmpty()){logout();return;}super.onBackPressed();}

    void frame(String title,boolean inner){getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);screenToken++;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);setContentView(root);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(9),dp(7),dp(9),dp(7));bar.setBackground(grad(navy,navy2,0));TextView nav=tv(inner?"‹":"☰",31,white);nav.setGravity(Gravity.CENTER);nav.setContentDescription(inner?"بازگشت":"باز کردن منو");bar.addView(nav,new LinearLayout.LayoutParams(dp(52),dp(50)));TextView t=tv(title,18,white);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);bar.addView(t,new LinearLayout.LayoutParams(0,dp(50),1));TextView brand=tv("ساختمان‌یار",12,Color.rgb(190,224,220));brand.setGravity(Gravity.CENTER);bar.addView(brand,new LinearLayout.LayoutParams(dp(92),dp(50)));root.addView(bar,new LinearLayout.LayoutParams(-1,dp(66)));busyBar=new ProgressBar(this);busyBar.setIndeterminate(true);busyBar.setVisibility(View.GONE);root.addView(busyBar,new LinearLayout.LayoutParams(-1,dp(4)));ScrollView sv=new ScrollView(this);sv.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(16),dp(16),dp(16),dp(32));content.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);sv.addView(content);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));drawer=new LinearLayout(this);drawer.setOrientation(LinearLayout.VERTICAL);drawer.setPadding(dp(14),dp(16),dp(14),dp(22));drawer.setBackgroundColor(white);drawer.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.addView(drawer,new LinearLayout.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*.86),-1));drawer.setVisibility(View.GONE);nav.setOnClickListener(v->{if(inner)backPage();else toggleDrawer();});}

    void toggleDrawer(){if(drawer!=null)drawer.setVisibility(drawer.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE);}

    void open(String id){if(history.isEmpty()||!history.peekLast().equals(id))history.addLast(id);show(id);}

    void show(String id){if("manager".equals(id))managerHome();else if("units".equals(id))units();else if("charges".equals(id))charges();else if("repairs".equals(id))repairs();else if("payments".equals(id))payments();else if("cashbox".equals(id))cashbox();else if("plans".equals(id))plans();else if("resident".equals(id))residentHome();else if("resident_pay".equals(id))residentPay();else if("admin".equals(id))adminHome();else if("admin_buildings".equals(id))adminBuildings();else if("admin_plans".equals(id))adminPlans();else if("admin_settings".equals(id))adminSettings();else showLogin();}

    void backPage(){if(drawer!=null&&drawer.getVisibility()==View.VISIBLE){drawer.setVisibility(View.GONE);return;}if(history.size()>1){history.removeLast();show(history.peekLast());}else logout();}

    void logout(){session="";role="";if(securePrefs!=null)securePrefs.edit().clear().apply();history.clear();showLogin();}

