void saveSession(String a,String r,String role){if(securePrefs!=null)securePrefs.edit().putString("session",a).putString("refresh_token",r==null?"":r).putString("role",role==null?"":role).apply();}

    void restoreSession(){if(securePrefs==null){showLogin();return;}String saved=securePrefs.getString("session","");String refresh=securePrefs.getString("refresh_token","");String savedRole=securePrefs.getString("role","");if(saved.isEmpty()||refresh.isEmpty()){showLogin();return;}session=saved;role=savedRole;restoring=true;io.submit(()->{try{JSONObject b=new JSONObject().put("action","refresh_session").put("refresh_token",refresh);JSONObject j=new JSONObject(rawPost(b,null));if(j.has("error"))throw new Exception(j.getString("error"));session=j.optString("access_token",j.getString("session"));String nr=j.optString("refresh_token",refresh);role=j.optString("role",role);securePrefs.edit().putString("session",session).putString("refresh_token",nr).putString("role",role).apply();history.clear();history.addLast("resident".equals(role)?"resident":"manager");runOnUiThread(()->{restoring=false;if("resident".equals(role))residentHome();else if("manager".equals(role))managerHome();else showLogin();});}catch(Exception e){restoring=false;securePrefs.edit().clear().apply();session="";role="";runOnUiThread(this::showLogin);}});}
        void login(String u,String p,String r){if(u.isEmpty()||p.isEmpty()){toast("نام کاربری و رمز عبور را وارد کنید");return;}final int t=screenToken;io.submit(()->{try{JSONObject b=new JSONObject().put("action",r.equals("resident")?"login_resident":"login_manager").put("username",u).put("password",p);JSONObject j=new JSONObject(post(b,null));if(j.has("error"))throw new Exception(j.getString("error"));session=j.getString("session");role=r;saveSession(session,j.optString("refresh_token",""),role);history.clear();history.addLast(r.equals("resident")?"resident":"manager");runOnUiThread(()->{if(t!=screenToken)return;if("resident".equals(r))residentHome();else managerHome();});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}});}

